class Solution { fun nodesBetweenCriticalPoints(head:ListNode?):IntArray{var previous=head!!;var current=head.next!!;var index=1;var first=-1;var last=-1;var minimum=Int.MAX_VALUE;while(current.next!=null){if((current.`val`>previous.`val`&&current.`val`>current.next!!.`val`)||(current.`val`<previous.`val`&&current.`val`<current.next!!.`val`)){if(first<0)first=index else minimum=minOf(minimum,index-last);last=index};previous=current;current=current.next!!;index++};return if(minimum==Int.MAX_VALUE)intArrayOf(-1,-1) else intArrayOf(minimum,last-first)} }
